// frontend/src/pages/dashboard/DashboardPage.js
import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { projectsAPI, teamAPI, workersAPI, attendanceAPI, companiesAPI } from '../../services/api';
import { useAuth } from '../../context/AuthContext';
import { usePermissions } from '../../context/PermissionsContext';
import AppLayout from '../../components/layout/AppLayout';
import RoleBadge from '../../components/ui/RoleBadge';

// ── Formatters ────────────────────────────────────────────────────────────────

const fmtFCFA = (n) => {
  if (n == null) return '—';
  const num = parseFloat(n);
  if (num >= 1_000_000_000) return `${(num / 1_000_000_000).toFixed(1)} Mrd`;
  if (num >= 1_000_000)     return `${(num / 1_000_000).toFixed(1)} M`;
  if (num >= 1_000)         return `${(num / 1_000).toFixed(0)} K`;
  return num.toLocaleString('fr-FR');
};

const fmtDate = (d) => {
  if (!d) return '—';
  return new Date(d + 'T00:00:00').toLocaleDateString('fr-FR', { day: '2-digit', month: 'short' });
};

const STATUS_CFG = {
  planifie: { label: 'Planifié',  color: '#6366F1', bg: 'rgba(99,102,241,0.12)'  },
  en_cours: { label: 'En cours',  color: '#F59E0B', bg: 'rgba(245,158,11,0.12)'  },
  suspendu: { label: 'Suspendu',  color: '#EF4444', bg: 'rgba(239,68,68,0.12)'   },
  termine:  { label: 'Terminé',   color: '#10B981', bg: 'rgba(16,185,129,0.12)'  },
};

const WEATHER = { ensoleille:'☀️', nuageux:'☁️', pluvieux:'🌧️', venteux:'💨', orageux:'⛈️' };

const PURCHASE_STATUS = {
  livre:      { label: 'Livré',    color: '#10B981' },
  commande:   { label: 'Commandé', color: '#3B82F6' },
  en_attente: { label: 'Attente',  color: '#F59E0B' },
  annule:     { label: 'Annulé',   color: '#EF4444' },
};

// ── Shared UI ─────────────────────────────────────────────────────────────────

function KPI({ label, value, sub, color = '#F59E0B', alert, icon }) {
  return (
    <div style={{
      background: '#111827',
      border: `1px solid ${alert ? 'rgba(239,68,68,0.4)' : 'rgba(255,255,255,0.07)'}`,
      borderRadius: 12, padding: '20px 22px', position: 'relative',
    }}>
      {alert && (
        <span style={{
          position: 'absolute', top: 10, right: 10,
          width: 8, height: 8, borderRadius: '50%',
          background: '#EF4444', boxShadow: '0 0 6px #EF4444',
        }} />
      )}
      {icon && <div style={{ fontSize: 22, marginBottom: 8 }}>{icon}</div>}
      <div style={{
        fontSize: 26, fontWeight: 800,
        color: alert ? '#EF4444' : color,
        fontFamily: 'Bebas Neue', letterSpacing: 1, marginBottom: 4,
      }}>{value ?? '—'}</div>
      <div style={{ fontSize: 11, color: '#6B7280', textTransform: 'uppercase', letterSpacing: '0.6px' }}>{label}</div>
      {sub && <div style={{ fontSize: 11, color: alert ? '#EF4444' : '#9CA3AF', marginTop: 4 }}>{sub}</div>}
    </div>
  );
}

function Alert({ text, type = 'warning' }) {
  const cfg = {
    warning: { bg: 'rgba(245,158,11,0.1)',  border: 'rgba(245,158,11,0.3)',  color: '#F59E0B',  icon: '⚠️' },
    danger:  { bg: 'rgba(239,68,68,0.08)', border: 'rgba(239,68,68,0.25)',  color: '#FCA5A5',  icon: '🔴' },
    info:    { bg: 'rgba(59,130,246,0.08)', border: 'rgba(59,130,246,0.2)', color: '#93C5FD',  icon: 'ℹ️' },
    success: { bg: 'rgba(16,185,129,0.08)', border: 'rgba(16,185,129,0.2)',color: '#34D399',   icon: '✅' },
  }[type];
  return (
    <div style={{
      background: cfg.bg, border: `1px solid ${cfg.border}`,
      borderRadius: 10, padding: '12px 16px', marginBottom: 20,
      fontSize: 13, color: cfg.color, display: 'flex', alignItems: 'center', gap: 10,
    }}>
      <span style={{ fontSize: 15 }}>{cfg.icon}</span> {text}
    </div>
  );
}

function Card({ children, style = {} }) {
  return (
    <div style={{
      background: '#111827', border: '1px solid rgba(255,255,255,0.07)',
      borderRadius: 14, padding: 22, ...style,
    }}>
      {children}
    </div>
  );
}

function SectionTitle({ children, action, actionTo, actionFn }) {
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
      <h2 style={{ fontFamily: 'Bebas Neue', fontSize: 18, color: '#fff', letterSpacing: 1, margin: 0 }}>{children}</h2>
      {action && (actionTo
        ? <Link to={actionTo} style={{ fontSize: 12, color: '#F59E0B', textDecoration: 'none', fontWeight: 600 }}>{action} →</Link>
        : <button onClick={actionFn} style={{ background: 'none', border: 'none', fontSize: 12, color: '#F59E0B', cursor: 'pointer', fontWeight: 600, padding: 0 }}>{action} →</button>
      )}
    </div>
  );
}

function ProgressBar({ pct, color, height = 7 }) {
  const c = color || (pct > 85 ? '#EF4444' : pct > 60 ? '#F59E0B' : '#3B82F6');
  return (
    <div style={{ height, background: 'rgba(255,255,255,0.07)', borderRadius: height / 2, overflow: 'hidden' }}>
      <div style={{ height: '100%', width: `${Math.min(100, pct || 0)}%`, background: c, borderRadius: height / 2, transition: 'width 0.7s ease' }} />
    </div>
  );
}

function StatusBadge({ status }) {
  const cfg = STATUS_CFG[status] || STATUS_CFG.planifie;
  return (
    <span style={{ padding: '2px 10px', borderRadius: 100, fontSize: 11, fontWeight: 600, color: cfg.color, background: cfg.bg }}>
      {cfg.label}
    </span>
  );
}

function ProjectRow({ p }) {
  return (
    <Link to={`/projects/${p.id}`} style={{ textDecoration: 'none' }}>
      <div style={{
        display: 'flex', alignItems: 'center', gap: 12,
        padding: '11px 14px', borderRadius: 10,
        background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.06)',
        marginBottom: 8, cursor: 'pointer', transition: 'background 0.15s',
      }}
        onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,255,255,0.06)'}
        onMouseLeave={e => e.currentTarget.style.background = 'rgba(255,255,255,0.03)'}
      >
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 13, fontWeight: 600, color: '#fff', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{p.name}</div>
          {p.location && <div style={{ fontSize: 11, color: '#6B7280' }}>📍 {p.location}</div>}
        </div>
        <StatusBadge status={p.status} />
        {p.progress_pct != null && (
          <span style={{ fontSize: 12, color: '#9CA3AF', fontWeight: 600, minWidth: 36, textAlign: 'right' }}>
            {p.progress_pct}%
          </span>
        )}
      </div>
    </Link>
  );
}

function EmptyState({ icon, text }) {
  return (
    <div style={{ textAlign: 'center', padding: '32px 0', color: '#4B5563' }}>
      <div style={{ fontSize: 32, marginBottom: 8 }}>{icon}</div>
      <div style={{ fontSize: 13 }}>{text}</div>
    </div>
  );
}

// ── Off-site alert row (Director dashboard) ───────────────────────────────────
function OffSiteRow({ a }) {
  return (
    <div style={{
      display: 'flex', gap: 12, padding: '10px 14px', borderRadius: 8,
      background: 'rgba(239,68,68,0.08)', border: '1px solid rgba(239,68,68,0.2)',
      marginBottom: 8,
    }}>
      <span style={{ fontSize: 18 }}>🔴</span>
      <div style={{ flex: 1 }}>
        <div style={{ fontSize: 13, fontWeight: 600, color: '#FCA5A5' }}>{a.worker_name}</div>
        <div style={{ fontSize: 11, color: '#6B7280' }}>
          {a.project_name} · {a.distance_from_site}m du site · {a.check_type === 'in' ? 'Entrée' : 'Sortie'}
        </div>
      </div>
      <div style={{ fontSize: 11, color: '#6B7280', alignSelf: 'center' }}>
        {new Date(a.timestamp).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' })}
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// ROLE DASHBOARDS
// ══════════════════════════════════════════════════════════════════════════════

// A — App Owner: SaaS infrastructure view
function DashboardAppOwner({ stats, companies }) {
  return (
    <>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 14, marginBottom: 28 }}>
        <KPI label="Entreprises"         value={stats?.companies_count || companies.length} icon="🏢" color="#fff" />
        <KPI label="Entreprises actives" value={stats?.active_companies || 0}               icon="✅" color="#10B981" />
        <KPI label="Utilisateurs total"  value={stats?.total_users || 0}                   icon="👥" color="#F59E0B" />
        <KPI label="Projets total"       value={stats?.total_projects || 0}                icon="🏗️" color="#6366F1" />
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>
        <Card>
          <SectionTitle action="Gérer" actionTo="/companies">Entreprises clientes</SectionTitle>
          {companies.length === 0
            ? <EmptyState icon="🏢" text="Aucune entreprise." />
            : companies.slice(0, 8).map(c => (
              <div key={c.id} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '10px 0', borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
                <div style={{ width: 36, height: 36, borderRadius: 8, background: 'rgba(255,255,255,0.07)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 16 }}>🏢</div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 13, fontWeight: 600, color: '#fff' }}>{c.name}</div>
                  <div style={{ fontSize: 11, color: '#6B7280' }}>{c.country} · {c.users_count} utilisateurs · {c.projects_count} projets</div>
                </div>
                <span style={{
                  padding: '2px 10px', borderRadius: 100, fontSize: 10, fontWeight: 700,
                  background: c.subscription === 'pro' ? 'rgba(245,158,11,0.15)' : 'rgba(156,163,175,0.1)',
                  color: c.subscription === 'pro' ? '#F59E0B' : '#9CA3AF',
                }}>{c.subscription.toUpperCase()}</span>
              </div>
            ))
          }
        </Card>
        <Card>
          <SectionTitle>Monitoring plateforme</SectionTitle>
          <Alert text="Vue infrastructure — accès exclusif App Owner." type="info" />
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, marginTop: 8 }}>
            {[
              { label: 'Abonnements trial', value: companies.filter(c => c.subscription === 'trial').length, color: '#9CA3AF' },
              { label: 'Abonnements pro',   value: companies.filter(c => c.subscription === 'pro').length,   color: '#F59E0B' },
              { label: 'Inactives',         value: companies.filter(c => !c.is_active).length,               color: '#EF4444' },
              { label: 'Enterprise',        value: companies.filter(c => c.subscription === 'enterprise').length, color: '#10B981' },
            ].map((s, i) => (
              <div key={i} style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 8, padding: '14px 16px' }}>
                <div style={{ fontSize: 24, fontWeight: 800, color: s.color, fontFamily: 'Bebas Neue' }}>{s.value}</div>
                <div style={{ fontSize: 11, color: '#6B7280', textTransform: 'uppercase', letterSpacing: '0.5px' }}>{s.label}</div>
              </div>
            ))}
          </div>
        </Card>
      </div>
    </>
  );
}

// B — Admin Entreprise (Directeur): strategic & financial
function DashboardDirecteur({ projects, stats, offSiteAlerts }) {
  const overBudget = projects.filter(p => (p.budget_consumed_pct || 0) > 100).length;
  const delayed    = projects.filter(p => p.is_delayed).length;
  const totalBudget = projects.reduce((a, p) => a + (parseFloat(p.budget) || 0), 0);
  const totalExp    = projects.reduce((a, p) => a + (parseFloat(p.actual_expenses) || 0), 0);
  const activeWorkers = projects.reduce((a, p) => a + (p.active_workers_today || 0), 0);

  return (
    <>
      {overBudget > 0 && <Alert text={`${overBudget} projet(s) en dépassement budgétaire`} type="danger" />}
      {delayed > 0    && <Alert text={`${delayed} projet(s) en retard sur la livraison`}   type="warning" />}
      {offSiteAlerts.length > 0 && <Alert text={`${offSiteAlerts.length} alerte(s) de pointage hors-site aujourd'hui`} type="danger" />}

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 14, marginBottom: 28 }}>
        <KPI label="Budget total"       value={`${fmtFCFA(totalBudget)} FCFA`}        icon="💼" color="#F59E0B" />
        <KPI label="Dépenses réelles"   value={`${fmtFCFA(totalExp)} FCFA`}           icon="💸" color="#EF4444" alert={totalExp > totalBudget} />
        <KPI label="Ouvriers actifs"    value={activeWorkers}                          icon="👷" color="#10B981" />
        <KPI label="Alertes hors-site"  value={offSiteAlerts.length}                  icon="📍" color="#EF4444" alert={offSiteAlerts.length > 0} />
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1.4fr 1fr', gap: 20 }}>
        <Card>
          <SectionTitle action="Voir tout" actionTo="/projects">Portefeuille projets</SectionTitle>
          {projects.length === 0
            ? <EmptyState icon="🏗️" text="Aucun projet." />
            : projects.map(p => (
              <div key={p.id} style={{ marginBottom: 16 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 5 }}>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <Link to={`/projects/${p.id}`} style={{ fontSize: 13, fontWeight: 600, color: '#fff', textDecoration: 'none', display: 'block', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{p.name}</Link>
                    <div style={{ fontSize: 11, color: '#6B7280' }}>📍 {p.location || '—'}</div>
                  </div>
                  <div style={{ display: 'flex', gap: 8, flexShrink: 0, marginLeft: 12 }}>
                    <StatusBadge status={p.status} />
                    <span style={{ fontSize: 12, fontWeight: 700, color: (p.budget_consumed_pct || 0) > 85 ? '#EF4444' : '#9CA3AF' }}>
                      {p.budget_consumed_pct ?? 0}%
                    </span>
                  </div>
                </div>
                <ProgressBar pct={p.budget_consumed_pct || 0} />
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 10, color: '#4B5563', marginTop: 3 }}>
                  <span>{fmtFCFA(p.actual_expenses)} / {fmtFCFA(p.budget)} FCFA</span>
                  <span>Avancement : {p.progress_pct || 0}%</span>
                </div>
              </div>
            ))
          }
        </Card>

        <Card>
          <SectionTitle>Alertes pointage hors-site 🔴</SectionTitle>
          {offSiteAlerts.length === 0
            ? <EmptyState icon="✅" text="Aucune alerte aujourd'hui." />
            : offSiteAlerts.slice(0, 6).map(a => <OffSiteRow key={a.id} a={a} />)
          }
          <div style={{ marginTop: 16 }}>
            <SectionTitle>Répartition par statut</SectionTitle>
            {['en_cours','planifie','suspendu','termine'].map(s => {
              const count = projects.filter(p => p.status === s).length;
              const cfg   = STATUS_CFG[s];
              return (
                <div key={s} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '7px 0', borderBottom: '1px solid rgba(255,255,255,0.04)' }}>
                  <span style={{ fontSize: 12, color: cfg.color }}>{cfg.label}</span>
                  <span style={{ fontSize: 14, fontWeight: 700, color: '#fff', fontFamily: 'Bebas Neue' }}>{count}</span>
                </div>
              );
            })}
          </div>
        </Card>
      </div>
    </>
  );
}

// C — Office Admin: HR & resources
function DashboardOfficeAdmin({ projects, team, workers, stats }) {
  return (
    <>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 14, marginBottom: 28 }}>
        <KPI label="Membres équipe"     value={team.length}              icon="👥" color="#22D3EE" />
        <KPI label="Ouvriers actifs"    value={workers.filter(w => w.is_active).length} icon="👷" color="#F59E0B" />
        <KPI label="Projets"            value={projects.length}          icon="🏗️" color="#6366F1" />
        <KPI label="Pointages auj."     value={stats?.attendance_today || 0} icon="📍" color="#10B981" />
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>
        <Card>
          <SectionTitle action="+ Inviter" actionTo="/team">Membres de l'équipe</SectionTitle>
          {team.length === 0
            ? <EmptyState icon="👥" text="Aucun membre." />
            : team.slice(0, 8).map(m => (
              <div key={m.id} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '9px 0', borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
                <div style={{ width: 34, height: 34, borderRadius: '50%', background: 'rgba(34,211,238,0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 13, fontWeight: 700, color: '#22D3EE', flexShrink: 0 }}>
                  {m.full_name?.[0]?.toUpperCase()}
                </div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 13, fontWeight: 600, color: '#fff' }}>{m.full_name}</div>
                  <div style={{ fontSize: 11, color: '#6B7280' }}>{m.platform_role_display}</div>
                </div>
                <span style={{ fontSize: 10, color: m.is_active ? '#10B981' : '#EF4444', background: m.is_active ? 'rgba(16,185,129,0.1)' : 'rgba(239,68,68,0.1)', padding: '2px 8px', borderRadius: 100 }}>
                  {m.is_active ? 'Actif' : 'Inactif'}
                </span>
              </div>
            ))
          }
        </Card>
        <Card>
          <SectionTitle action="+ Ajouter" actionTo="/team">Ouvriers enregistrés</SectionTitle>
          {workers.length === 0
            ? <EmptyState icon="👷" text="Aucun ouvrier enregistré." />
            : workers.slice(0, 8).map(w => (
              <div key={w.id} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '9px 0', borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
                <div style={{ width: 34, height: 34, borderRadius: '50%', background: 'rgba(245,158,11,0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 16 }}>👷</div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 13, fontWeight: 600, color: '#fff' }}>{w.full_name}</div>
                  <div style={{ fontSize: 11, color: '#6B7280' }}>{w.trade_display} · {fmtFCFA(w.daily_rate)} FCFA/j</div>
                </div>
                <span style={{ fontSize: 10, color: w.is_active ? '#10B981' : '#EF4444', padding: '2px 8px', borderRadius: 100, background: w.is_active ? 'rgba(16,185,129,0.1)' : 'rgba(239,68,68,0.1)' }}>
                  {w.is_active ? 'Actif' : 'Inactif'}
                </span>
              </div>
            ))
          }
        </Card>
