        <KPI label="Budget consommé" value={`${globalPct}%`} alert={globalPct > 85}                 icon="💰" color="#F59E0B" sub={`${fmtFCFA(totalExp)} / ${fmtFCFA(totalBudget)}`} />
        <KPI label="En cours"        value={projects.filter(p => p.status === 'en_cours').length}   icon="⚡" color="#F59E0B" />
        <KPI label="Rapports récents" value={reports.length}                                         icon="📓" color="#10B981" />
