              </div>
            ))
          }
        </Card>
        <Card>
          <SectionTitle>Rapports disponibles</SectionTitle>
          {reports.length === 0
            ? <EmptyState icon="📄" text="Aucun rapport disponible." />
            : reports.map(r => (
              <Link key={r.id} to={`/projects/${r.project_id}/reports/${r.id}`} style={{ textDecoration: 'none' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '11px 0', borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
                  <div style={{ width: 40, height: 40, borderRadius: 8, background: 'rgba(16,185,129,0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                    <span style={{ fontSize: 11, fontWeight: 700, color: '#34D399' }}>PDF</span>
                  </div>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: 13, fontWeight: 600, color: '#fff' }}>Rapport — {fmtDate(r.report_date)}</div>
                    <div style={{ fontSize: 11, color: '#6B7280' }}>{r.project_name} · {r.workers_count} ouvriers</div>
                  </div>
                  {r.is_validated
                    ? <span style={{ fontSize: 11, color: '#10B981' }}>✓ Validé</span>
                    : <span style={{ fontSize: 11, color: '#6B7280' }}>Brouillon</span>
                  }
                </div>
              </Link>
            ))
          }
        </Card>
      </div>
    </>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// MAIN DASHBOARD PAGE
// ══════════════════════════════════════════════════════════════════════════════

const PAGE_TITLES = {
  app_owner:        'Infrastructure Plateforme',
  admin_entreprise: 'Vue Stratégique & Financière',
  office_admin:     'Ressources Humaines & Admin',
  chef_projet:      'Mes Projets — Gantt & Budget',
  chef_chantier:    'Mon Chantier du Jour',
  chef_equipe:      'Mon Équipe — Pointage',
  ingenieur:        'Documents & Plans Techniques',
  qhse:             'Contrôle Qualité & Sécurité',
  magasinier:       'Stocks & Livraisons',
  comptable:        'Trésorerie & Achats',
  client:           'Suivi de Vos Projets',
};

const CTA = {
  admin_entreprise: { label: 'Nouveau projet',     to: '/projects/new', color: '#F59E0B' },
  office_admin:     { label: '+ Inviter membre',   to: '/team',         color: '#22D3EE' },
  chef_projet:      { label: 'Rapport IA',         to: '/reports',      color: '#818CF8' },
  chef_chantier:    { label: '📍 Pointage',        to: '/pointage',     color: '#FB923C' },
  chef_equipe:      { label: '📍 Pointer équipe',  to: '/pointage',     color: '#FCD34D' },
  ingenieur:        { label: 'Documents',          to: '/documents',    color: '#34D399' },
  qhse:             { label: 'Rapport QHSE',       to: '/qhse',         color: '#F87171' },
  magasinier:       { label: 'Registre stock',     to: '/stock',        color: '#9CA3AF' },
  comptable:        { label: 'Trésorerie',         to: '/treasury',     color: '#4ADE80' },
};

export default function DashboardPage() {
  const { user }                      = useAuth();
  const { role, roleColor, roleIcon } = usePermissions();

  const [projects,     setProjects]     = useState([]);
  const [stats,        setStats]        = useState(null);
  const [team,         setTeam]         = useState([]);
  const [workers,      setWorkers]      = useState([]);
  const [companies,    setCompanies]    = useState([]);
  const [attendance,   setAttendance]   = useState(null);
  const [offSiteAlerts,setOffSiteAlerts]= useState([]);
  const [loading,      setLoading]      = useState(true);

  useEffect(() => {
    const calls = [
      projectsAPI.list().catch(() => ({ data: [] })),
      projectsAPI.getDashboardStats().catch(() => ({ data: null })),
    ];

    if (['app_owner', 'admin_entreprise', 'office_admin'].includes(role)) {
      calls.push(teamAPI.list().catch(() => ({ data: [] })));
    }
    if (['office_admin', 'admin_entreprise', 'app_owner'].includes(role)) {
      calls.push(workersAPI.list().catch(() => ({ data: [] })));
    }
    if (role === 'app_owner') {
      calls.push(companiesAPI.list().catch(() => ({ data: [] })));
    }

    Promise.all(calls).then(results => {
      const [pRes, sRes, ...rest] = results;
      setProjects(pRes.data || []);
      setStats(sRes.data);

      let idx = 0;
      if (['app_owner', 'admin_entreprise', 'office_admin'].includes(role)) {
        setTeam(rest[idx]?.data || []);
        idx++;
      }
      if (['office_admin', 'admin_entreprise', 'app_owner'].includes(role)) {
        setWorkers(rest[idx]?.data || []);
        idx++;
      }
      if (role === 'app_owner') {
        setCompanies(rest[idx]?.data || []);
      }
    }).finally(() => setLoading(false));
  }, [role]);

  // Load attendance for chantier roles
  useEffect(() => {
    if (!['chef_chantier', 'chef_equipe'].includes(role)) return;
    const projects_loaded = projects.filter(p => p.id);
    if (projects_loaded.length === 0) return;
    const firstProjectId = projects_loaded[0]?.id;
    if (!firstProjectId) return;
    attendanceAPI.summary(firstProjectId)
      .then(r => setAttendance(r.data))
      .catch(() => {});
  }, [role, projects]);

  // Load off-site alerts for director
  useEffect(() => {
    if (role !== 'admin_entreprise' && role !== 'app_owner') return;
    if (projects.length === 0) return;
    Promise.all(
      projects.filter(p => p.status === 'en_cours').map(p =>
        attendanceAPI.alerts(p.id).then(r => r.data?.alerts || []).catch(() => [])
      )
    ).then(results => setOffSiteAlerts(results.flat()));
  }, [role, projects]);

  const cta = CTA[role];
  const companyName = user?.company?.name || user?.company_name || '';

  return (
    <AppLayout>
      <div style={{ padding: '32px 36px' }}>

        {/* ── Header ── */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 28 }}>
          <div>
            <p style={{ color: '#6B7280', fontSize: 12, margin: '0 0 4px', fontFamily: 'Barlow Condensed', letterSpacing: 0.5, textTransform: 'uppercase' }}>
              {new Date().toLocaleDateString('fr-FR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
            </p>
            <h1 style={{ fontFamily: 'Bebas Neue', fontSize: 26, color: '#fff', letterSpacing: 1, margin: '0 0 8px' }}>
              {PAGE_TITLES[role] || 'Tableau de bord'}
            </h1>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <RoleBadge role={role} size="sm" />
              <span style={{ fontSize: 12, color: '#6B7280' }}>
                {user?.full_name}{companyName ? ` · ${companyName}` : ''}
              </span>
            </div>
          </div>

          <div style={{ display: 'flex', gap: 10, alignItems: 'center', flexShrink: 0 }}>
            <Link to="/projects" style={{ padding: '9px 18px', borderRadius: 8, border: '1px solid rgba(255,255,255,0.1)', background: 'transparent', color: '#9CA3AF', fontSize: 13, fontWeight: 600, textDecoration: 'none' }}>
              Mes projets
            </Link>
            {cta && (
              <Link to={cta.to} style={{ padding: '9px 20px', borderRadius: 8, background: cta.color, color: '#0D0D1A', fontSize: 13, fontWeight: 700, textDecoration: 'none' }}>
                {cta.label}
              </Link>
            )}
          </div>
        </div>

        {/* ── Content ── */}
        {loading ? (
          <div style={{ textAlign: 'center', padding: '80px 0' }}>
            <div style={{ width: 36, height: 36, border: '3px solid #F59E0B', borderTopColor: 'transparent', borderRadius: '50%', animation: 'spin 1s linear infinite', margin: '0 auto 14px' }} />
            <p style={{ color: '#6B7280', fontSize: 14 }}>Chargement...</p>
          </div>
        ) : (
          <>
            {role === 'app_owner'        && <DashboardAppOwner    stats={stats}     companies={companies} />}
            {role === 'admin_entreprise' && <DashboardDirecteur   projects={projects} stats={stats} offSiteAlerts={offSiteAlerts} />}
            {role === 'office_admin'     && <DashboardOfficeAdmin projects={projects} team={team}   workers={workers} stats={stats} />}
            {role === 'chef_projet'      && <DashboardChefProjet  projects={projects} stats={stats} />}
            {role === 'chef_chantier'    && <DashboardChefChantier projects={projects} stats={stats} attendance={attendance} />}
            {role === 'chef_equipe'      && <DashboardChefEquipe  projects={projects} attendance={attendance} />}
            {role === 'ingenieur'        && <DashboardIngenieur   projects={projects} />}
            {role === 'qhse'             && <DashboardQHSE        projects={projects} stats={stats} />}
            {role === 'magasinier'       && <DashboardMagasinier  projects={projects} stats={stats} />}
            {role === 'comptable'        && <DashboardComptable   projects={projects} stats={stats} />}
            {role === 'client'           && <DashboardClient      projects={projects} stats={stats} />}
          </>
        )}
      </div>
    </AppLayout>
  );
}
